const items = $input.all();
if (!items || items.length === 0) {
  const wanted = $('Config').first().json['Topic Title'];
  throw new Error(`No topic found titled "${wanted}". It must exactly match a topic already created in Phase 1.`);
}
const topic = items[0].json;
return [{ json: { topic_id: topic.id, topic_title: topic.title, channel_id: topic.channel_id } }];

const items = $input.all();
if (!items || items.length === 0) {
  throw new Error('No video with qc_passed_at set found for this topic. Run Phase 5 (phase5-qc.json) and get an overall_pass first.');
}
const video = items[0].json;
return [{ json: { id: video.id, channel_id: video.channel_id, script_id: video.script_id } }];

const items = $input.all();
if (!items || items.length === 0) {
  throw new Error('No "final" script found for this topic — Phase 2 must have completed with a Critic pass.');
}
return [{ json: { script_content: items[0].json.content } }];

const items = $input.all();
if (!items || items.length === 0) {
  throw new Error('Channel not found for this topic — data inconsistency, check the topics/channels tables.');
}
const channel = items[0].json;
return [{ json: { name: channel.name, niche: channel.niche, brand_voice: channel.brand_voice, made_for_kids: !!channel.made_for_kids } }];

const items = $input.all();
const approvedSynthetic = items
  .map(i => i.json)
  .filter(a => (a.type === 'ai_image' || a.type === 'ai_video') && a.status === 'approved');
return [{ json: {
  synthetic_media_disclosure_computed: approvedSynthetic.length > 0,
  approved_synthetic_asset_types: [...new Set(approvedSynthetic.map(a => a.type))]
} }];

const script = $('Pick Script Row').first().json.script_content;
const channel = $('Pick Channel Info Row').first().json;
const synthetic = $('Compute Synthetic Media Flag').first().json;

const syntheticNote = synthetic.synthetic_media_disclosure_computed
  ? `This video DOES include approved AI-generated media (asset types: ${synthetic.approved_synthetic_asset_types.join(', ')}). It requires the synthetic-media disclosure.`
  : `This video does NOT currently have any approved AI-generated (ai_image/ai_video) assets — only non-synthetic assets are approved so far. Based on that, disclosure is likely not required, but say so explicitly rather than assuming.`;

const madeForKidsNote = channel.made_for_kids
  ? `This channel IS set to made_for_kids. The self-declared made-for-kids flag will be set on upload — do not write a description or tags that assume personalized ads, comments, or audience data will be available, none of those exist on made-for-kids uploads.`
  : `This channel is NOT made_for_kids.`;

const system = `You are the Publishing agent. Generate upload metadata — you don't touch video
content, only packaging.

Script: ${script}

Channel niche: ${channel.niche}
Brand voice: ${channel.brand_voice || '(none specified)'}
Recent performance notes: No analytics history yet.

${madeForKidsNote}

Synthetic media check (already determined from this video's real asset records,
do not contradict it — just factor it into your description/disclosure notes):
${syntheticNote}

Produce:
- 3 title variants (under 60 characters), each with a one-line note on the
  psychological angle it plays (curiosity gap / stakes / specificity)
- A description: first 2 lines hook a reader browsing (this shows before "show
  more"), then a fuller summary, then a placeholder for timestamps
- 15-20 tags, ordered most to least specific
- A recommendation on which title to launch with, based on recent performance

Titles must accurately represent the video's content — no claim in the title the
video doesn't deliver on. This is a retention and trust issue, not just a policy one.

Also confirm: does this video contain AI-generated or synthetically altered media
requiring disclosure under YouTube's policies? If yes, flag it so the upload step
sets the disclosure field.

--- RESPONSE FORMAT ---

Respond with JSON only, no prose outside the JSON, matching exactly this shape:
{
  "title_variants": [
    { "title": string, "angle": string },
    { "title": string, "angle": string },
    { "title": string, "angle": string }
  ],
  "recommended_title": string,
  "recommendation_reason": string,
  "description": string,
  "tags": [string, ...],
  "synthetic_media_disclosure": boolean,
  "synthetic_media_reasoning": string
}
"tags" must have between 15 and 20 items.`;

return [{ json: { system } }];

const raw = $input.first().json["Claude's Publishing JSON"] || '';
let parsed = null;
let parseError = null;
try {
  const match = raw.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : raw);
} catch (e) {
  parseError = e.message;
}
const valid = parsed &&
  Array.isArray(parsed.title_variants) && parsed.title_variants.length === 3 &&
  parsed.title_variants.every(t => t.title && t.angle) &&
  parsed.recommended_title && parsed.description &&
  Array.isArray(parsed.tags) && parsed.tags.length >= 15 && parsed.tags.length <= 20;
if (parseError || !valid) {
  throw new Error('Could not parse a valid Publishing JSON (needs title_variants: 3 items, recommended_title, description, tags: 15-20 items). Paste error: ' + (parseError || 'missing/malformed fields'));
}

const computed = $('Compute Synthetic Media Flag').first().json;
const pastedDisclosure = !!parsed.synthetic_media_disclosure;
const disclosureAgrees = pastedDisclosure === computed.synthetic_media_disclosure_computed;

const channel = $('Pick Channel Info Row').first().json;
const videoId = $('Pick Video Row').first().json.id;

return [{ json: {
  video_id: videoId,
  row: {
    video_id: videoId,
    title_variants: parsed.title_variants,
    recommended_title: parsed.recommended_title,
    recommendation_reason: parsed.recommendation_reason || null,
    description: parsed.description,
    tags: parsed.tags,
    synthetic_media_disclosure: computed.synthetic_media_disclosure_computed,
    made_for_kids: channel.made_for_kids
  },
  pasted_disclosure_claim: pastedDisclosure,
  pasted_disclosure_reasoning: parsed.synthetic_media_reasoning || null,
  computed_disclosure: computed.synthetic_media_disclosure_computed,
  disclosure_agrees: disclosureAgrees
} }];

const shorts = $input.all().map(i => i.json).filter(s => s && s.id);
const jobs = shorts.map(s => ({ short_id: s.id, target: 'short', status: 'queued' }));
return [{ json: { jobs, has_shorts: jobs.length > 0 } }];

const parsed = $('Parse Publishing JSON').first().json;
return [{ json: {
  result: 'SEO metadata saved and publish_jobs queued (not actually uploaded — no YouTube OAuth wired).',
  topic: $('Pick Topic Row').first().json.topic_title,
  video_id: parsed.video_id,
  recommended_title: parsed.row.recommended_title,
  synthetic_media_disclosure: parsed.computed_disclosure,
  disclosure_agreed_with_paste: parsed.disclosure_agrees,
  short_publish_jobs_queued: $('Build Short Publish Jobs').first().json.jobs.length
} }];
